from rest_framework.generics import ListAPIView
from rest_framework import permissions
from .models import DiscoveryDocument
from .serializers import DiscoveryDocumentSerializer

class DiscoveryDocumentKeyFilterView(ListAPIView):
    serializer_class = DiscoveryDocumentSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        tag_key = self.request.query_params.get('meta_key')
        if not tag_key:
            return DiscoveryDocument.objects.none()

        return DiscoveryDocument.objects.filter(
            matter__assigned_firm=self.request.user.law_firm,
            metadata__has_key=tag_key
        )
